<script setup lang="ts">import {ref,onMounted,watch} from 'vue';import {api} from '../../api';import {locale,t} from '../../locales';import '../../styles/app.scss';const channels=ref<any[]>([]);const active=ref(0);async function load(){channels.value=await api.contacts()}onMounted(load);watch(locale,load);function copy(){uni.setClipboardData({data:channels.value[active.value]?.account||''});uni.showToast({title:t('已复制'),icon:'none'})}</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('客服联系方式')}}</text></view><view class="inner-main"><view class="inner-heading">{{t('联系客服')}}</view><view class="inner-subtitle">{{t('选择您的联系方式')}}</view><view class="contact-list"><view v-for="(c,i) in channels" :key="c.type" class="contact-row" :class="{selected:active===i}" @click="active=i"><view><text class="contact-icon">{{c.type==='Telegram'?'➤':'◉'}}</text><view><text class="list-title">{{c.type}}</text><text class="list-meta">{{c.account}}</text></view></view><text v-if="active===i" class="check">✓</text></view></view><view class="qr-placeholder"><text>{{t('扫码加入客服')}}</text><view>QR</view></view><button class="action-button" @click="copy">{{t('复制联系方式')}}</button></view></view></template>
<style scoped>.contact-list{margin-top:24rpx}.contact-row{display:flex;align-items:center;justify-content:space-between;padding:15rpx;border:1rpx solid var(--cf-line);border-radius:12rpx;background:#fff}.contact-row+.contact-row{margin-top:12rpx}.contact-row.selected{border-color:var(--cf-brand);background:#EFF6FF}.contact-row>view{display:flex;align-items:center;gap:12rpx}.contact-icon{display:grid;place-items:center;width:42rpx;height:42rpx;border-radius:50%;background:#229ED9;color:#fff}.contact-row:nth-child(2) .contact-icon{background:#25D366}.check{color:var(--cf-brand);font-weight:800}.qr-placeholder{display:flex;align-items:center;flex-direction:column;gap:10rpx;margin:28rpx 0;color:var(--cf-soft);font-size:17rpx}.qr-placeholder view{display:grid;place-items:center;width:128rpx;height:128rpx;border:1rpx solid var(--cf-line);background:#fff;color:var(--cf-text);font-size:22rpx;letter-spacing:8rpx}</style>
